440:     private String getFacebookAttributionId(final Context context) {
441:         try {
442:             @SuppressLint("PackageManagerGetSignatures")
443:             Signature[] signatures = null;
444:             if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
445:                 SigningInfo signingInfo = context.getPackageManager().getPackageInfo(
446:                         "com.facebook.katana",
447:                         PackageManager.GET_SIGNING_CERTIFICATES).signingInfo;
448:                 if (signingInfo != null) {
449:                     signatures = signingInfo.getApkContentsSigners();
450:                 }
451:             } else {
452:                 signatures = context.getPackageManager().getPackageInfo(
453:                 "com.facebook.katana",
454:                 PackageManager.GET_SIGNATURES).signatures;
455:             }
456: 
457:             if (signatures == null || signatures.length != 1) {
458:                 // Unable to find the correct signatures for this APK
459:                 return null;
460:             }
461:             Signature facebookApkSignature = signatures[0];
462:             if (!OFFICIAL_FACEBOOK_SIGNATURE.equals(facebookApkSignature.toCharsString())) {
463:                 // not the official Facebook application
464:                 return null;
465:             }
466: 
467:             final ContentResolver contentResolver = context.getContentResolver();
468:             final Uri uri = Uri.parse("content://com.facebook.katana.provider.AttributionIdProvider");
469:             final String columnName = "aid";
470:             final String[] projection = {columnName};
471:             final Cursor cursor = contentResolver.query(uri, projection, null, null, null);
472: 
473:             if (cursor == null) {
474:                 return null;
475:             }
476:             if (!cursor.moveToFirst()) {
477:                 cursor.close();
478:                 return null;
479:             }
480: 
481:             final String attributionId = cursor.getString(cursor.getColumnIndex(columnName));
482:             cursor.close();
483:             return attributionId;
484:         } catch (Exception e) {
485:             return null;
486:         }
487:     }

